#!/usr/bin/env bash
# Writes `wasm-imports.ts` into the given bindings directory, mapping every JS module the staged
# wasm imports to that module's exports.
#
# The `index.ts` generated by ubrn only resolves the wasm-bindgen glue (`<lib>_bg.js`). With JSPI,
# the wasm also imports wasm-bindgen snippets directly, such as the keystore's OPFS VFS. The player
# fills anything unresolved with stubs that throw when called, so those imports must be supplied as
# well. Snippet paths contain a crate hash, which is why the list is generated after staging rather
# than written by hand.
#
# Usage: wasm-imports.sh <bindings dir> <lib name>
set -euo pipefail

if [ $# -ne 2 ]; then
    echo "usage: $0 <bindings dir> <lib name>" >&2
    exit 1
fi
dir=$1
lib=$2

# Module names as the wasm imports them: relative to the bindings directory.
modules=("./${lib}_bg.js")
if [ -d "$dir/snippets" ]; then
    while IFS= read -r snippet; do
        modules+=("./$snippet")
    done < <(cd "$dir" && find snippets -type f -name '*.js' | LC_ALL=C sort)
fi

{
    echo "// Generated by scripts/wasm-imports.sh. Do not edit."
    echo "// @ts-nocheck"
    for i in "${!modules[@]}"; do
        echo "import * as module$i from \"${modules[$i]}\";"
    done
    echo
    echo "export const wasmImports: Record<string, Record<string, unknown>> = {"
    for i in "${!modules[@]}"; do
        echo "    \"${modules[$i]}\": module$i,"
    done
    echo "};"
} > "$dir/wasm-imports.ts"
